contracts/erc8004/IdentityRegistryTestne.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";

/**
 * @title IdentityRegistryTestnet
 * @notice GuardianAI TESTNET STAND-IN implementing the canonical ERC-8004
 *         Identity Registry interface subset used by the GuardianAI registrar:
 *           register(string) -> uint256          (mints to msg.sender, emits Transfer)
 *           setMetadata(uint256,string,bytes)     (owner-only writes)
 *           getMetadata(uint256,string) view      -> bytes
 *           ownerOf(uint256) view                 -> address
 *
 * @dev This is NOT the audited reference contract from
 *      github.com/erc-8004/erc-8004-contracts — it is an ABI-faithful minimal
 *      stand-in for testnet rehearsal only. The canonical CREATE2 deployment
 *      (0x8004A169FB4a3325136EB29fA0ceB6D2e539a432) is mainnet-only today and
 *      absent from Base/Ethereum Sepolia (verified on-chain 2026-08-23 via
 *      eth_getCode). Mainnet integrations MUST target the canonical address.
 */
contract IdentityRegistryTestnet is ERC721 {
    string public constant REGISTRATION_TYPE =
        "https://eips.ethereum.org/EIPS/eip-8004#registration-v1";

    uint256 private _nextId = 1;
    mapping(uint256 => string) private _agentURI;
    mapping(uint256 => mapping(string => bytes)) private _metadata;

    event MetadataSet(uint256 indexed agentId, string indexed key, bytes value);

    error AgentNotFound();

    constructor()
        ERC721(
            "GuardianAI Testnet IdentityRegistry (ERC-8004 interface)",
            "GAI-8004"
        )
    {}

    function register(string calldata agentURI_) external returns (uint256 id) {
        id = _nextId++;
        _safeMint(msg.sender, id);
        _agentURI[id] = agentURI_;
    }

    function setMetadata(
        uint256 agentId,
        string calldata key,
        bytes calldata value
    ) external {
        if (_ownerOf(agentId) == address(0)) revert AgentNotFound();
        require(_ownerOf(agentId) == msg.sender, "NotAgentOwner");
        _metadata[agentId][key] = value;
        emit MetadataSet(agentId, key, value);
    }

    function getMetadata(
        uint256 agentId,
        string calldata key
    ) external view returns (bytes memory) {
        return _metadata[agentId][key];
    }

    function getAgentUri(uint256 agentId) external view returns (string memory) {
        return _agentURI[agentId];
    }
}

contracts/GuardianCircuitBreaker.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./interfaces/IGuardianRiskAttestation.sol";
import "./interfaces/IGuardianThreatFeed.sol";

/**
 * @title GuardianCircuitBreaker
 * @notice Abstract contract that DeFi protocols inherit for live Guardian protection.
 *         Provides modifiers that check risk attestations and threat feeds before
 *         allowing sensitive operations to execute.
 *
 * @dev    Usage: inherit this contract and apply `guardianProtected` to sensitive
 *         functions (withdraw, swap, mint, bridge). If Guardian has flagged the
 *         caller or the contract itself, the transaction reverts.
 *
 *         Two modifier variants:
 *         - guardianProtected:       fail-open if no attestation exists (gradual adoption)
 *         - guardianProtectedStrict: fail-closed if no attestation exists (high-value vaults)
 *
 *         Access control is self-contained via circuitBreakerAdmin — does not force
 *         inheriting contracts to use any specific Ownable pattern.
 *
 *         No TransactionBlocked events: emit before revert discards logs. Off-chain
 *         blocked-attempt monitoring comes from the RPC Relay's blocked_transactions
 *         table (Phase 1). Custom errors provide sufficient on-chain revert data.
 *
 *         Immutable registry addresses: a Guardian redeployment orphans inheriting
 *         contracts — deliberate, matches how other protocols handle oracle/registry upgrades.
 *
 * Example:
 *   contract MyVault is GuardianCircuitBreaker {
 *       constructor(address _attestation, address _threatFeed)
 *           GuardianCircuitBreaker(_attestation, _threatFeed, msg.sender) {}
 *
 *       function withdraw(uint256 amount) external guardianProtected {
 *           // Only executes if caller is not flagged & contract risk score is healthy
 *       }
 *   }
 */
abstract contract GuardianCircuitBreaker {

    // ── State ────────────────────────────────────────────────────────────

    IGuardianRiskAttestation public immutable riskAttestation;
    IGuardianThreatFeed     public immutable threatFeed;

    address public circuitBreakerAdmin;
    uint16  public riskScoreThreshold = 6000;   // Block if score < 60% (below grade D)
    bool    public circuitBreakerActive = true;

    // ── Events ───────────────────────────────────────────────────────────

    event CircuitBreakerToggled(bool active);
    event RiskThresholdUpdated(uint16 oldThreshold, uint16 newThreshold);
    event CircuitBreakerAdminTransferred(address indexed previousAdmin, address indexed newAdmin);

    // ── Errors ───────────────────────────────────────────────────────────

    error CallerFlaggedMalicious(address caller);
    error ContractRiskTooHigh(uint16 currentScore, uint16 threshold);
    error NotCircuitBreakerAdmin();
    error ZeroAddress();

    // ── Modifiers ────────────────────────────────────────────────────────

    modifier onlyCircuitBreakerAdmin() {
        if (msg.sender != circuitBreakerAdmin) revert NotCircuitBreakerAdmin();
        _;
    }

    // ── Constructor ──────────────────────────────────────────────────────

    constructor(address _riskAttestation, address _threatFeed, address _admin) {
        if (_riskAttestation == address(0)) revert ZeroAddress();
        if (_threatFeed == address(0)) revert ZeroAddress();
        if (_admin == address(0)) revert ZeroAddress();
        riskAttestation     = IGuardianRiskAttestation(_riskAttestation);
        threatFeed          = IGuardianThreatFeed(_threatFeed);
        circuitBreakerAdmin = _admin;
    }

    // ── Core Modifiers ───────────────────────────────────────────────────

    /**
     * @notice Core modifier — fail-open for unaudited contracts.
     *         Apply to sensitive functions (withdraw, swap, mint, bridge).
     *         Checks: (1) caller not in threat feed, (2) contract risk score healthy.
     *         If no attestation exists, allows execution (gradual adoption).
     */
    modifier guardianProtected() {
        if (circuitBreakerActive) {
            // Check 1: Is the caller flagged as malicious?
            (bool isMalicious, ) = threatFeed.isMalicious(msg.sender);
            if (isMalicious) revert CallerFlaggedMalicious(msg.sender);

            // Check 2: Is this contract's risk score below threshold?
            try riskAttestation.getAttestation(address(this), "monad") returns (
                IGuardianRiskAttestation.Attestation memory att
            ) {
                if (att.score < riskScoreThreshold) {
                    revert ContractRiskTooHigh(att.score, riskScoreThreshold);
                }
            } catch {
                // No attestation exists — fail-open (allow execution)
            }
        }
        _;
    }

    /**
     * @notice Strict modifier — fail-closed for unaudited contracts.
     *         If no attestation exists, reverts (high-value vault protection).
     */
    modifier guardianProtectedStrict() {
        if (circuitBreakerActive) {
            (bool isMalicious, ) = threatFeed.isMalicious(msg.sender);
            if (isMalicious) revert CallerFlaggedMalicious(msg.sender);

            IGuardianRiskAttestation.Attestation memory att =
                riskAttestation.getAttestation(address(this), "monad");
            if (att.score < riskScoreThreshold) {
                revert ContractRiskTooHigh(att.score, riskScoreThreshold);
            }
        }
        _;
    }

    // ── Admin Functions (access-controlled) ──────────────────────────────

    function setCircuitBreakerActive(bool _active) external onlyCircuitBreakerAdmin {
        circuitBreakerActive = _active;
        emit CircuitBreakerToggled(_active);
    }

    function setRiskScoreThreshold(uint16 _threshold) external onlyCircuitBreakerAdmin {
        uint16 old = riskScoreThreshold;
        riskScoreThreshold = _threshold;
        emit RiskThresholdUpdated(old, _threshold);
    }

    function transferCircuitBreakerAdmin(address _newAdmin) external onlyCircuitBreakerAdmin {
        if (_newAdmin == address(0)) revert ZeroAddress();
        address old = circuitBreakerAdmin;
        circuitBreakerAdmin = _newAdmin;
        emit CircuitBreakerAdminTransferred(old, _newAdmin);
    }
}

contracts/GuardianCortexAnchor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title GuardianCortexAnchor
 * @notice Immutable on-chain record of Merkle tree roots from GuardianAI Cortex.
 *         Each root commits a batch of AI agent decision hashes, providing a
 *         tamper-proof audit trail anchored to an EVM chain.
 *
 * @dev    Uses OpenZeppelin Ownable2Step (safe ownership transfer),
 *         Pausable (emergency stop), and ReentrancyGuard (future-proof).
 *
 *         Only the contract owner (the Guardian deployer wallet) can commit roots.
 *         Verification is public — anyone can check if a leaf is in a committed batch.
 */
contract GuardianCortexAnchor is Ownable2Step, Pausable, ReentrancyGuard {

    // ── Types ────────────────────────────────────────────────────────────

    struct Commitment {
        bytes32  merkleRoot;
        uint256  eventCount;
        bytes32  agentHash;       // keccak256(agentId)
        uint256  periodStart;     // UNIX timestamp
        uint256  periodEnd;       // UNIX timestamp
        uint256  committedAt;     // block.timestamp at commit time
        uint256  blockNumber;     // block.number at commit time
    }

    // ── State ────────────────────────────────────────────────────────────

    /// @notice Maximum commitments per agent (prevents unbounded array growth)
    uint256 public constant MAX_COMMITMENTS_PER_AGENT = 100_000;

    /// @notice Global list of all commitments (append-only)
    Commitment[] public commitments;

    /// @notice agentHash => list of commitment indices
    mapping(bytes32 => uint256[]) public agentCommitments;

    /// @notice merkleRoot => commitment index (0 = not found, actual index + 1)
    mapping(bytes32 => uint256) public rootIndex;

    /// @notice Total number of events anchored across all agents
    uint256 public totalEventsAnchored;

    // ── Events ───────────────────────────────────────────────────────────

    event RootCommitted(
        bytes32 indexed merkleRoot,
        bytes32 indexed agentHash,
        uint256 eventCount,
        uint256 periodStart,
        uint256 periodEnd,
        uint256 commitmentIndex
    );

    // ── Errors ───────────────────────────────────────────────────────────

    error EmptyRoot();
    error ZeroEventCount();
    error InvalidPeriod();
    error RootAlreadyCommitted(bytes32 root);
    error AgentLimitReached(bytes32 agentHash, uint256 limit);

    // ── Constructor ──────────────────────────────────────────────────────

    constructor() Ownable(msg.sender) {}

    // ── Write Functions ──────────────────────────────────────────────────

    /**
     * @notice Commit a Merkle root representing a batch of Cortex events.
     * @param _merkleRoot   The SHA-256 Merkle root hash (as bytes32)
     * @param _eventCount   Number of events in this batch
     * @param _agentHash    keccak256 hash of the agent ID
     * @param _periodStart  UNIX timestamp of the first event in the batch
     * @param _periodEnd    UNIX timestamp of the last event in the batch
     */
    function commitRoot(
        bytes32 _merkleRoot,
        uint256 _eventCount,
        bytes32 _agentHash,
        uint256 _periodStart,
        uint256 _periodEnd
    ) external onlyOwner whenNotPaused nonReentrant {
        if (_merkleRoot == bytes32(0)) revert EmptyRoot();
        if (_eventCount == 0) revert ZeroEventCount();
        if (_periodEnd < _periodStart) revert InvalidPeriod();
        if (rootIndex[_merkleRoot] != 0) revert RootAlreadyCommitted(_merkleRoot);
        if (agentCommitments[_agentHash].length >= MAX_COMMITMENTS_PER_AGENT) {
            revert AgentLimitReached(_agentHash, MAX_COMMITMENTS_PER_AGENT);
        }

        uint256 idx = commitments.length;
        commitments.push(Commitment({
            merkleRoot:  _merkleRoot,
            eventCount:  _eventCount,
            agentHash:   _agentHash,
            periodStart: _periodStart,
            periodEnd:   _periodEnd,
            committedAt: block.timestamp,
            blockNumber: block.number
        }));

        rootIndex[_merkleRoot] = idx + 1;  // +1 so 0 means "not found"
        agentCommitments[_agentHash].push(idx);
        totalEventsAnchored += _eventCount;

        emit RootCommitted(
            _merkleRoot, _agentHash, _eventCount,
            _periodStart, _periodEnd, idx
        );
    }

    // ── Read Functions ───────────────────────────────────────────────────

    /**
     * @notice Check if a Merkle root has been committed.
     * @return exists True if the root was committed
     * @return commitment The commitment data (zeroed if not found)
     */
    function getCommitment(bytes32 _merkleRoot)
        external view returns (bool exists, Commitment memory commitment)
    {
        uint256 idx = rootIndex[_merkleRoot];
        if (idx == 0) return (false, commitment);
        return (true, commitments[idx - 1]);
    }

    /**
     * @notice Verify a SHA-256 Merkle inclusion proof on-chain.
     * @param _leaf  The leaf hash
     * @param _proof Array of sibling hashes from leaf to root
     * @param _root  The expected Merkle root
     * @return valid True if the proof checks out
     *
     * @dev Uses sha256 precompile (address 0x02) to match the Python
     *      Merkle tree implementation. Pairs are sorted before hashing
     *      to ensure deterministic ordering.
     *
     * @dev CA-2: Gas cost scales linearly with _proof.length (O(n) sha256
     *      hashes). This is caller-borne — verifyInclusion() is pure and
     *      is not called by any other on-chain contract, so no third party
     *      can grief other callers by inflating proof size. Off-chain RPC
     *      clients should be aware of this for very deep trees.
     */
    function verifyInclusion(
        bytes32 _leaf,
        bytes32[] calldata _proof,
        bytes32 _root
    ) external pure returns (bool valid) {
        bytes32 current = _leaf;
        for (uint256 i = 0; i < _proof.length; i++) {
            bytes32 sibling = _proof[i];
            // Sort pair for deterministic ordering (matches Python implementation)
            if (current > sibling) {
                current = sha256(abi.encodePacked(sibling, current));
            } else {
                current = sha256(abi.encodePacked(current, sibling));
            }
        }
        return current == _root;
    }

    /**
     * @notice Get the total number of commitments.
     */
    function getCommitmentCount() external view returns (uint256) {
        return commitments.length;
    }

    /**
     * @notice Get commitment indices for an agent.
     * @param _agentHash keccak256 hash of the agent ID
     * @return indices Array of commitment indices
     *
     * @dev CA-1: Returns the full agentCommitments[_agentHash] array in one
     *      call. Gas cost scales with the number of commitments made by the
     *      agent (O(n) memory copy). This is caller-borne — getAgentCommitments()
     *      is a view function not called by any other on-chain contract, so no
     *      third party can grief other callers by inflating an agent's array.
     *      Off-chain callers querying very active agents should be aware of
     *      the RPC response size. A paginated variant can be added if needed.
     */
    function getAgentCommitments(bytes32 _agentHash)
        external view returns (uint256[] memory indices)
    {
        return agentCommitments[_agentHash];
    }

    // ── Admin Functions ──────────────────────────────────────────────────

    /**
     * @notice Pause the contract (emergency stop). Only owner.
     */
    function pause() external onlyOwner { _pause(); }

    /**
     * @notice Unpause the contract. Only owner.
     */
    function unpause() external onlyOwner { _unpause(); }
}

