// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title GuardianInsuranceLedger
 * @notice Anchors signed insurance certificates on-chain, storing integrity hashes
 *         and validity periods to verify the insurance status of AI agents.
 */
contract GuardianInsuranceLedger is Ownable2Step, Pausable, ReentrancyGuard {

    // ── Types ────────────────────────────────────────────────────────────

    struct Certificate {
        bytes32 agentHash;      // keccak256(agentId)
        uint256 periodStart;    // UNIX timestamp
        uint256 periodEnd;      // UNIX timestamp
        bytes32 certHash;       // Hash of the full certificate document
        string riskLevel;       // e.g. "LOW", "MEDIUM", "HIGH"
        uint256 issuedAt;
        bool revoked;
    }

    // ── State ────────────────────────────────────────────────────────────

    /// @notice Maps certificate ID (bytes32) to its data
    mapping(bytes32 => Certificate) public certificates;

    /// @notice List of all certificate IDs
    // NOTE: Growing array can lead to high gas costs. Pagination should be added if off-chain enumeration becomes a bottleneck.
    bytes32[] public certificateIds;

    uint256 public constant MAX_CERTIFICATES = 100_000;

    // ── Events ───────────────────────────────────────────────────────────

    event CertificateIssued(
        bytes32 indexed certId,
        bytes32 indexed agentHash,
        uint256 periodStart,
        uint256 periodEnd,
        bytes32 certHash,
        string riskLevel
    );

    event CertificateRevoked(bytes32 indexed certId);

    // ── Errors ───────────────────────────────────────────────────────────

    error CertificateAlreadyExists(bytes32 certId);
    error CertificateNotFound(bytes32 certId);
    error InvalidAgentHash();
    error InvalidPeriod();
    error InvalidCertHash();
    error CertificateAlreadyRevoked(bytes32 certId);
    error CertificateLimitReached();
    /// @notice _riskLevel must be exactly "LOW", "MEDIUM", or "HIGH" (case-sensitive, uppercase).
    error InvalidRiskLevel(string riskLevel);
    /// @notice _certId parameter was zero bytes32 (IL-1: distinguished from a genuine lookup-miss).
    error InvalidCertId();

    // ── Constructor ──────────────────────────────────────────────────────

    constructor() Ownable(msg.sender) {}

    // ── Write Functions ──────────────────────────────────────────────────

    /**
     * @notice Issue a new insurance certificate for an agent.
     *
     * @dev    Check ordering (IL-2): structural input validation first, then
     *         business-logic checks (cap, duplicate). This ensures a caller
     *         cannot distinguish cap-reached from invalid-input via error type.
     */
    function issueCertificate(
        bytes32 _certId,
        bytes32 _agentHash,
        uint256 _periodStart,
        uint256 _periodEnd,
        bytes32 _certHash,
        string calldata _riskLevel
    ) external onlyOwner whenNotPaused nonReentrant {
        // ── 1. Structural input validation (fast, no state reads) ────────
        if (_certId == bytes32(0))   revert InvalidCertId();
        if (_agentHash == bytes32(0)) revert InvalidAgentHash();
        if (_certHash == bytes32(0)) revert InvalidCertHash();
        if (_periodEnd < _periodStart) revert InvalidPeriod();
        require(bytes(_riskLevel).length <= 32, "Risk level too long");
        if (!_validRiskLevel(_riskLevel)) revert InvalidRiskLevel(_riskLevel);

        // ── 2. Business-logic / state-dependent checks ───────────────────
        if (certificateIds.length >= MAX_CERTIFICATES) {
            revert CertificateLimitReached();
        }
        if (certificates[_certId].issuedAt != 0) revert CertificateAlreadyExists(_certId);

        certificates[_certId] = Certificate({
            agentHash:   _agentHash,
            periodStart: _periodStart,
            periodEnd:   _periodEnd,
            certHash:    _certHash,
            riskLevel:   _riskLevel,
            issuedAt:    block.timestamp,
            revoked:     false
        });

        certificateIds.push(_certId);

        emit CertificateIssued(_certId, _agentHash, _periodStart, _periodEnd, _certHash, _riskLevel);
    }

    /**
     * @notice Revoke a certificate.
     */
    function revokeCertificate(bytes32 _certId) external onlyOwner whenNotPaused nonReentrant {
        Certificate storage cert = certificates[_certId];
        if (cert.issuedAt == 0) revert CertificateNotFound(_certId);
        if (cert.revoked) revert CertificateAlreadyRevoked(_certId);

        cert.revoked = true;

        emit CertificateRevoked(_certId);
    }

    // ── Read Functions ───────────────────────────────────────────────────

    /**
     * @notice Fetch certificate details.
     */
    function getCertificate(bytes32 _certId) external view returns (Certificate memory) {
        Certificate memory cert = certificates[_certId];
        if (cert.issuedAt == 0) revert CertificateNotFound(_certId);
        return cert;
    }

    /**
     * @notice Get total certificate count.
     */
    function getCertificateCount() external view returns (uint256) {
        return certificateIds.length;
    }

    /**
     * @notice Paginated read of certificateIds for off-chain enumeration (IL-3).
     * @param offset Zero-based start index into the certificateIds array.
     * @param limit  Maximum number of IDs to return. Capped internally at 1000.
     * @return page  Slice of certificate IDs beginning at `offset`.
     *
     * @dev  The public certificateIds array auto-getter provides index-by-index
     *       access; this function returns a contiguous slice to avoid forcing
     *       off-chain clients to make O(n) individual calls as the registry grows.
     *       Gas cost is caller-borne (view function).
     */
    function getCertificateIdsPage(uint256 offset, uint256 limit)
        external
        view
        returns (bytes32[] memory page)
    {
        uint256 total = certificateIds.length;
        if (offset >= total) return page; // empty slice
        uint256 cap = limit > 1000 ? 1000 : limit;
        uint256 end = offset + cap;
        if (end > total) end = total;
        page = new bytes32[](end - offset);
        for (uint256 i = 0; i < page.length; i++) {
            page[i] = certificateIds[offset + i];
        }
    }

    // ── Admin Functions ──────────────────────────────────────────────────

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    // ── Internal Helpers ─────────────────────────────────────────────────

    /**
     * @dev Returns true iff riskLevel is exactly "LOW", "MEDIUM", or "HIGH".
     *      Casing is uppercase to match the Python _assess_risk() output convention.
     */
    function _validRiskLevel(string calldata riskLevel) internal pure returns (bool) {
        bytes32 h = keccak256(bytes(riskLevel));
        return h == keccak256(bytes("LOW"))
            || h == keccak256(bytes("MEDIUM"))
            || h == keccak256(bytes("HIGH"));
    }
}

contracts/GuardianInterlockRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title GuardianInterlockRegistry
 * @notice Stores cross-agent interlock proofs on-chain, enabling mutual verification
 *         of interaction history between autonomous AI agents.
 *
 * @dev    IR-2 fix: Added soft-revoke mechanism (revokeInterlock) so that a bad
 *         registration — e.g. one produced by a compromised owner key with fabricated
 *         agent/proof data — can be corrected without deleting the historical record.
 *
 *         Design rationale: Interlock proofs are intentionally append-only (the
 *         InterlockRegistered event is permanent on-chain, providing non-repudiation).
 *         However, permanence of the *event log* is distinct from permanence of
 *         *current validity* — the same distinction made by GuardianInsuranceLedger's
 *         revokeCertificate(). A revoked record remains inspectable via getInterlock()
 *         but verifyInterlock() reverts InterlockAlreadyRevoked, so downstream
 *         protocols querying proof validity get the correct answer.
 *
 *         revokeInterlock() is whenNotPaused: revocation during an active pause/
 *         incident-response window is dangerous — a compromised owner key could use
 *         revocation as a cover-up tool to erase evidence of fabricated interlocks
 *         before the pause can be lifted. Requiring the contract to be unpaused to
 *         revoke ensures the emergency-stop and the corrective-action paths remain
 *         independent. (This matches InsuranceLedger's revokeCertificate() precedent.)
 */
contract GuardianInterlockRegistry is Ownable2Step, Pausable, ReentrancyGuard {

    // ── Types ────────────────────────────────────────────────────────────

    struct InterlockProof {
        bytes32 agentA;       // keccak256(agentA_id)
        bytes32 agentB;       // keccak256(agentB_id)
        bytes32 proofHash;
        uint256 nonce;
        uint256 registeredAt;
        bool    revoked;      // true after revokeInterlock(); record preserved for history
    }

    // ── State ────────────────────────────────────────────────────────────

    /// @notice Maps interlockId to its proof details
    mapping(bytes32 => InterlockProof) public registry;

    /// @notice List of all registered interlock IDs
    bytes32[] public interlockIds;

    // ── Events ───────────────────────────────────────────────────────────

    event InterlockRegistered(
        bytes32 indexed interlockId,
        bytes32 indexed agentA,
        bytes32 indexed agentB,
        bytes32 proofHash,
        uint256 nonce
    );

    /// @notice Emitted when an owner revokes a previously registered interlock.
    ///         The record is preserved in storage and inspectable via getInterlock();
    ///         only verifyInterlock() treats a revoked record as invalid.
    event InterlockRevoked(bytes32 indexed interlockId);

    // ── Errors ───────────────────────────────────────────────────────────

    error InterlockAlreadyExists(bytes32 interlockId);
    error InvalidAgentHash();
    error InvalidProofHash();
    error InterlockNotFound(bytes32 interlockId);
    /// @notice Thrown by verifyInterlock() and revokeInterlock() when the record
    ///         has already been revoked.
    error InterlockAlreadyRevoked(bytes32 interlockId);

    // ── Constructor ──────────────────────────────────────────────────────

    constructor() Ownable(msg.sender) {}

    // ── Write Functions ──────────────────────────────────────────────────

    /**
     * @notice Register a mutual interlock proof between two agents.
     * @param _agentA    keccak256 hash of agent A ID
     * @param _agentB    keccak256 hash of agent B ID
     * @param _proofHash Hash of the interlock interaction proof
     * @param _nonce     Nonce for uniqueness
     * @return interlockId The computed unique ID of this interlock
     */
    function registerInterlock(
        bytes32 _agentA,
        bytes32 _agentB,
        bytes32 _proofHash,
        uint256 _nonce
    ) external onlyOwner whenNotPaused nonReentrant returns (bytes32 interlockId) {
        if (_agentA == bytes32(0) || _agentB == bytes32(0)) revert InvalidAgentHash();
        if (_proofHash == bytes32(0)) revert InvalidProofHash();

        interlockId = keccak256(abi.encodePacked(_agentA, _agentB, _proofHash, _nonce));
        if (registry[interlockId].registeredAt != 0) revert InterlockAlreadyExists(interlockId);

        registry[interlockId] = InterlockProof({
            agentA:       _agentA,
            agentB:       _agentB,
            proofHash:    _proofHash,
            nonce:        _nonce,
            registeredAt: block.timestamp,
            revoked:      false
        });

        interlockIds.push(interlockId);

        emit InterlockRegistered(interlockId, _agentA, _agentB, _proofHash, _nonce);
    }

    // ── Write Functions (admin) ──────────────────────────────────────────

    /**
     * @notice Revoke a previously registered interlock proof.
     * @param _interlockId The ID of the interlock to revoke.
     *
     * @dev    The record is marked revoked in storage but NOT deleted.
     *         getInterlock() continues to return the full record including
     *         revoked = true, preserving the tamper-evident audit trail.
     *         verifyInterlock() reverts InterlockAlreadyRevoked for revoked records.
     *
     *         whenNotPaused: prevents a compromised owner key from using revocation
     *         as a cover-up tool during an active incident (see contract NatSpec).
     */
    function revokeInterlock(bytes32 _interlockId) external onlyOwner whenNotPaused {
        InterlockProof storage proof = registry[_interlockId];
        if (proof.registeredAt == 0) revert InterlockNotFound(_interlockId);
        if (proof.revoked) revert InterlockAlreadyRevoked(_interlockId);
        proof.revoked = true;
        emit InterlockRevoked(_interlockId);
    }

    // ── Read Functions ───────────────────────────────────────────────────

    /**
     * @notice Verify and return the proof hash for a registered, non-revoked interlock.
     * @param _interlockId The ID of the interlock.
     * @return proofHash   The stored proof hash.
     * @dev    Reverts InterlockAlreadyRevoked if the record has been revoked.
     *         Use getInterlock() to inspect revoked records.
     */
    function verifyInterlock(bytes32 _interlockId) external view returns (bytes32 proofHash) {
        InterlockProof memory proof = registry[_interlockId];
        if (proof.registeredAt == 0) revert InterlockNotFound(_interlockId);
        if (proof.revoked) revert InterlockAlreadyRevoked(_interlockId);
        return proof.proofHash;
    }

    /**
     * @notice Get details of a registered interlock proof.
     */
    function getInterlock(bytes32 _interlockId) external view returns (InterlockProof memory) {
        InterlockProof memory proof = registry[_interlockId];
        if (proof.registeredAt == 0) revert InterlockNotFound(_interlockId);
        return proof;
    }

    /**
     * @notice Get total number of registered interlocks.
     */
    function getInterlockCount() external view returns (uint256) {
        return interlockIds.length;
    }

    // ── Admin Functions ──────────────────────────────────────────────────

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }
}

contracts/GuardianPassportSBT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title GuardianPassportSBT
 * @notice Non-transferable Soulbound Token (SBT) representing an AI agent's
 *         trust passport in the GuardianAI ecosystem. Implements ERC-5192
 *         (Minimal Soulbound NFTs) on top of OpenZeppelin's ERC-721.
 *
 * @dev    Transfers are blocked by overriding _update(). The token can only
 *         be minted to a new address or burned (revoked). Uses Ownable2Step
 *         for safe ownership transfer and Pausable for emergency stops.
 *
 *         ERC-5192 compliance: emits Locked(tokenId) on mint, locked() returns true.
 */
contract GuardianPassportSBT is ERC721, Ownable2Step, Pausable, ReentrancyGuard {

    // ── Types ────────────────────────────────────────────────────────────

    enum Tier { UNVERIFIED, SILVER, GOLD, DIAMOND }

    struct Passport {
        bytes32   agentHash;      // keccak256(agentId)
        Tier      tier;
        uint256   trustScore;     // Scaled by 100 (e.g. 8550 = 85.50)
        uint256   issuedAt;
        uint256   updatedAt;
        bool      revoked;
        string    metadataURI;    // Off-chain metadata pointer
    }

    // ── State ────────────────────────────────────────────────────────────

    /// @notice tokenId => passport data
    mapping(uint256 => Passport) public passports;

    /// @notice agentHash => tokenId (0 = not minted)
    mapping(bytes32 => uint256) public agentToken;

    /// @notice Auto-incrementing token ID counter
    uint256 private _nextTokenId;

    /// @notice Total active (non-revoked) passports
    uint256 public activePassportCount;

    // ── Events ───────────────────────────────────────────────────────────

    /// @notice ERC-5192: Emitted when a token is locked (soulbound)
    event Locked(uint256 indexed tokenId);

    /// @notice Emitted when a passport's trust score is updated
    event ScoreUpdated(
        uint256 indexed tokenId,
        bytes32 indexed agentHash,
        uint256 newScore,
        Tier    newTier
    );

    /// @notice Emitted when a passport is revoked
    event PassportRevoked(
        uint256 indexed tokenId,
        bytes32 indexed agentHash,
        uint256 revokedAt
    );

    // ── Errors ───────────────────────────────────────────────────────────

    error SoulboundTransferBlocked();
    error AgentAlreadyHasPassport(bytes32 agentHash);
    error PassportNotFound(uint256 tokenId);
    error PassportAlreadyRevoked(uint256 tokenId);
    error InvalidScore();

    // ── Constructor ──────────────────────────────────────────────────────

    constructor()
        ERC721("GuardianAI Passport", "GAPASS")
        Ownable(msg.sender)
    {
        _nextTokenId = 1;  // Start from 1 (0 reserved for "not found")
    }

    // ── Soulbound Enforcement (ERC-5192) ─────────────────────────────────

    /**
     * @dev Override _update to block all transfers. Only mint (from=0) and
     *      burn (to=0) are allowed. This makes the token soulbound.
     */
    function _update(
        address to,
        uint256 tokenId,
        address auth
    ) internal override returns (address) {
        address from = _ownerOf(tokenId);

        // Allow mint (from == 0) and burn (to == 0), block transfers
        if (from != address(0) && to != address(0)) {
            revert SoulboundTransferBlocked();
        }

        return super._update(to, tokenId, auth);
    }

    /**
     * @notice ERC-5192: Returns true if the token is locked (always true for SBTs).
     * @param tokenId The token to check
     * @return True (all tokens are permanently locked)
     */
    function locked(uint256 tokenId) external view returns (bool) {
        _requireOwned(tokenId);  // Revert if token doesn't exist
        return true;
    }

    // ── Write Functions ──────────────────────────────────────────────────

    /**
     * @notice Mint a new passport SBT for an AI agent.
     * @param _to         Address to receive the SBT (agent's owner wallet)
     * @param _agentHash  keccak256 hash of the agent ID
     * @param _score      Initial trust score (scaled by 100, e.g. 5000 = 50.00)
     * @param _metadataURI Off-chain metadata URI
     * @return tokenId    The minted token ID
     */
    function mint(
        address _to,
        bytes32 _agentHash,
        uint256 _score,
        string calldata _metadataURI
    ) external onlyOwner whenNotPaused nonReentrant returns (uint256 tokenId) {
        // ── Checks ───────────────────────────────────────────────────────
        if (agentToken[_agentHash] != 0) {
            revert AgentAlreadyHasPassport(_agentHash);
        }
        if (_score > 10000) revert InvalidScore();

        // ── Effects ──────────────────────────────────────────────────────
        // All state is written BEFORE the external call (_safeMint) to
        // comply with Checks-Effects-Interactions and prevent reentrancy
        // via onERC721Received callbacks. If _safeMint reverts, Solidity's
        // atomic transaction semantics roll back all writes below.
        tokenId = _nextTokenId++;

        passports[tokenId] = Passport({
            agentHash:   _agentHash,
            tier:        _classifyTier(_score),
            trustScore:  _score,
            issuedAt:    block.timestamp,
            updatedAt:   block.timestamp,
            revoked:     false,
            metadataURI: _metadataURI
        });

        agentToken[_agentHash] = tokenId;
        activePassportCount++;

        emit Locked(tokenId);  // ERC-5192 compliance

        // ── Interactions ─────────────────────────────────────────────────
        // _safeMint calls onERC721Received on the recipient if it is a contract.
        // A reentrant call to mint() will find agentToken[_agentHash] != 0
        // and revert with AgentAlreadyHasPassport.
        _safeMint(_to, tokenId);
    }

    /**
     * @notice Update the trust score and tier for an existing passport.
     * @param _tokenId  The passport token ID
     * @param _newScore New trust score (scaled by 100)
     */
    function updateScore(uint256 _tokenId, uint256 _newScore)
        external onlyOwner whenNotPaused
    {
        Passport storage p = passports[_tokenId];
        if (p.issuedAt == 0) revert PassportNotFound(_tokenId);
        if (p.revoked) revert PassportAlreadyRevoked(_tokenId);
        if (_newScore > 10000) revert InvalidScore();

        p.trustScore = _newScore;
        p.tier = _classifyTier(_newScore);
        p.updatedAt = block.timestamp;

        emit ScoreUpdated(_tokenId, p.agentHash, _newScore, p.tier);
    }

    /**
     * @notice Revoke (burn) a passport. The SBT is destroyed and the agent
     *         slot is freed for re-issuance.
     * @param _tokenId The passport token ID to revoke
     */
    function revoke(uint256 _tokenId) external onlyOwner {
        Passport storage p = passports[_tokenId];
        if (p.issuedAt == 0) revert PassportNotFound(_tokenId);
        if (p.revoked) revert PassportAlreadyRevoked(_tokenId);

        p.revoked = true;
        p.updatedAt = block.timestamp;
        activePassportCount--;

        // Free agent slot so a new passport can be minted
        delete agentToken[p.agentHash];

        // Burn the token
        _update(address(0), _tokenId, address(0));

        emit PassportRevoked(_tokenId, p.agentHash, block.timestamp);
    }

    // ── Read Functions ───────────────────────────────────────────────────

    /**
     * @notice Get full passport data for a token.
     */
    function getPassport(uint256 _tokenId)
        external view returns (Passport memory)
    {
        if (passports[_tokenId].issuedAt == 0) revert PassportNotFound(_tokenId);
        return passports[_tokenId];
    }

    /**
     * @notice Get the token ID for an agent (by agentHash).
     * @return tokenId 0 if no passport exists
     */
    function getAgentTokenId(bytes32 _agentHash)
        external view returns (uint256)
    {
        return agentToken[_agentHash];
    }

    /**
     * @notice ERC-165: Declare support for ERC-721, ERC-165, and ERC-5192.
     */
    function supportsInterface(bytes4 interfaceId)
        public view override returns (bool)
    {
        // ERC-5192 interface ID = 0xb45a3c0e
        return interfaceId == 0xb45a3c0e || super.supportsInterface(interfaceId);
    }

    // ── Admin Functions ──────────────────────────────────────────────────

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    // ── Internal ─────────────────────────────────────────────────────────

    function _classifyTier(uint256 _score) internal pure returns (Tier) {
        if (_score >= 9000) return Tier.DIAMOND;
        if (_score >= 7000) return Tier.GOLD;
        if (_score >= 4000) return Tier.SILVER;
        return Tier.UNVERIFIED;
    }
}

contracts/GuardianProtectedVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "./GuardianCircuitBreaker.sol";

/**
 * @title GuardianProtectedVault
 * @notice Reference implementation demonstrating how a DeFi protocol integrates
 *         Guardian circuit breaker protection. NOT intended for production deployment.
 *
 * @dev    This contract shows the integration pattern:
 *         1. Inherit GuardianCircuitBreaker
 *         2. Pass attestation and threat feed addresses to the constructor
 *         3. Apply guardianProtected or guardianProtectedStrict to sensitive functions
 *
 *         The vault accepts a single ERC-20 token for deposits/withdrawals.
 *         guardianProtected is used for normal operations (fail-open).
 *         guardianProtectedStrict is used for emergency operations (fail-closed).
 */
contract GuardianProtectedVault is GuardianCircuitBreaker, Ownable2Step, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    IERC20 public immutable token;
    mapping(address => uint256) public balances;

    event Deposited(address indexed user, uint256 amount);
    event Withdrawn(address indexed user, uint256 amount);
    event EmergencyWithdrawn(address indexed owner, uint256 amount);

    error InsufficientBalance(uint256 requested, uint256 available);
    error ZeroAmount();

    constructor(
        address _token,
        address _riskAttestation,
        address _threatFeed
    )
        GuardianCircuitBreaker(_riskAttestation, _threatFeed, msg.sender)
        Ownable(msg.sender)
    {
        if (_token == address(0)) revert ZeroAddress();
        token = IERC20(_token);
    }

    function deposit(uint256 _amount) external guardianProtected whenNotPaused nonReentrant {
        if (_amount == 0) revert ZeroAmount();
        // CEI fix: safeTransferFrom before updating balances to prevent reentrancy via ERC777/hook tokens
        token.safeTransferFrom(msg.sender, address(this), _amount);
        balances[msg.sender] += _amount;
        emit Deposited(msg.sender, _amount);
    }

    function withdraw(uint256 _amount) external guardianProtected whenNotPaused nonReentrant {
        if (_amount == 0) revert ZeroAmount();
        if (balances[msg.sender] < _amount) {
            revert InsufficientBalance(_amount, balances[msg.sender]);
        }
        balances[msg.sender] -= _amount;
        token.safeTransfer(msg.sender, _amount);
        emit Withdrawn(msg.sender, _amount);
    }

    function emergencyWithdraw() external guardianProtectedStrict onlyOwner {
        uint256 bal = token.balanceOf(address(this));
        if (bal > 0) {
            token.safeTransfer(owner(), bal);
        }
        emit EmergencyWithdrawn(owner(), bal);
    }

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }
}

contracts/GuardianRiskAttestation.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title GuardianRiskAttestation
 * @notice Stores on-chain risk score attestations for audited smart contracts,
 *         providing verifiable security assessments that other DeFi protocols can query.
 *
 * @dev    Changes vs initial deployment:
 *
 *         RA-1 (Pausable): Added Pausable inheritance and whenNotPaused on attest(),
 *         matching the pattern used by the other 4 GuardianAI on-chain contracts.
 *         The only call path (cortex_routes.py risk_attest_onchain) is an admin-only
 *         HTTP endpoint that already wraps the call in try/except → HTTP 400, so a
 *         paused revert surfaces gracefully rather than silently.
 *
 *         RA-3 (Grade allowlist): Replaced the non-empty string check with a
 *         configurable allowlist (_validGrades mapping, keyed by keccak256 of the
 *         grade string). Constructor bootstraps {A, B, C, D, F} — the exact 5 values
 *         produced by onchain_risk_scorer._grade(). Owner can extend the allowlist
 *         via setValidGrade() without redeployment, accommodating the broader 9-value
 *         Grade enum (A+, A, A-, B+, B, B-, C, D, F) already present in
 *         guardian/audit/models.py and the extra "C+" produced by crypto_scanner.py.
 *
 *         RA-4 (Silent overwrite): Previously, re-attesting an already-attested
 *         contract emitted only RiskAttested, indistinguishable from a first
 *         attestation. Now a separate AttestationUpdated event is emitted on overwrite
 *         so on-chain indexers can distinguish creation from update without off-chain
 *         state tracking.
 */
contract GuardianRiskAttestation is Ownable2Step, Pausable {

    // ── Types ────────────────────────────────────────────────────────────

    struct Attestation {
        uint16  score;           // 0–10000 (e.g. 9500 = 95.00%)
        string  grade;           // e.g. "A", "B+", "F"
        bytes32 signalsHash;     // keccak256 of the full signals JSON/metadata
        uint256 attestedAt;
        uint256 blockNumber;
    }

    // ── State ────────────────────────────────────────────────────────────

    /// @notice contractAddress => chain => Attestation
    mapping(address => mapping(string => Attestation)) public attestations;

    /// @notice Total number of unique (contractAddress, chain) pairs ever attested
    uint256 public totalAttestations;

    /// @dev Valid grade strings, keyed by keccak256(abi.encodePacked(grade)).
    ///      Bootstrapped in the constructor; extensible via setValidGrade().
    mapping(bytes32 => bool) private _validGrades;

    // ── Events ───────────────────────────────────────────────────────────

    /// @notice Emitted when a new (contractAddress, chain) pair is attested for the first time.
    event RiskAttested(
        address indexed contractAddress,
        string  indexed chain,
        uint16          score,
        string          grade,
        bytes32         signalsHash
    );

    /// @notice Emitted when an existing attestation is overwritten.
    ///         Distinct from RiskAttested so indexers can track updates vs. creations.
    event AttestationUpdated(
        address indexed contractAddress,
        string  indexed chain,
        uint16          score,
        string          grade,
        bytes32         signalsHash
    );

    /// @notice Emitted when the grade allowlist is changed.
    event ValidGradeSet(string grade, bool allowed);

    // ── Errors ───────────────────────────────────────────────────────────

    error InvalidScore();
    /// @notice grade is not in the on-chain allowlist. Use setValidGrade() to extend.
    error GradeNotAllowed(string grade);
    error AttestationNotFound();
    error InvalidGradeLength();

    // ── Constructor ──────────────────────────────────────────────────────

    constructor() Ownable(msg.sender) {
        // Bootstrap with the 5 grades currently produced by onchain_risk_scorer._grade():
        //   score >= 90 → "A", >= 80 → "B", >= 70 → "C", >= 60 → "D", else → "F"
        // The broader 9-value Grade enum in guardian/audit/models.py (A+, A, A-, B+, B,
        // B-, C, D, F) can be enabled by the owner via setValidGrade() without redeployment.
        _validGrades[keccak256(bytes("A"))] = true;
        _validGrades[keccak256(bytes("B"))] = true;
        _validGrades[keccak256(bytes("C"))] = true;
        _validGrades[keccak256(bytes("D"))] = true;
        _validGrades[keccak256(bytes("F"))] = true;
    }

    // ── Write functions ──────────────────────────────────────────────────

    /**
     * @notice Attest to a smart contract's risk score and security grade.
     * @param _contractAddress The contract being audited.
     * @param _chain           The chain name (e.g. "ethereum", "monad").
     * @param _score           The risk score (0–10000).
     * @param _grade           The letter grade — must be in the _validGrades allowlist.
     * @param _signalsHash     keccak256 hash of the audit signals JSON.
     *
     * @dev  Emits RiskAttested on first attestation for a (contract, chain) pair, or
     *       AttestationUpdated when overwriting an existing attestation (RA-4).
     */
    function attest(
        address        _contractAddress,
        string calldata _chain,
        uint16          _score,
        string calldata _grade,
        bytes32         _signalsHash
    ) external onlyOwner whenNotPaused {
        require(_contractAddress != address(0), "Invalid contract address");
        require(bytes(_chain).length > 0, "Invalid chain string");
        if (_score > 10000) revert InvalidScore();
        if (!_validGrades[keccak256(bytes(_grade))]) revert GradeNotAllowed(_grade);

        bool isNew = attestations[_contractAddress][_chain].attestedAt == 0;
        if (isNew) {
            totalAttestations++;
        }

        attestations[_contractAddress][_chain] = Attestation({
            score:       _score,
            grade:       _grade,
            signalsHash: _signalsHash,
            attestedAt:  block.timestamp,
            blockNumber: block.number
        });

        if (isNew) {
            emit RiskAttested(_contractAddress, _chain, _score, _grade, _signalsHash);
        } else {
            emit AttestationUpdated(_contractAddress, _chain, _score, _grade, _signalsHash);
        }
    }

    /**
     * @notice Add or remove a grade string from the allowlist.
     * @param grade   The grade string (1–3 bytes, e.g. "A", "B+", "A-").
     * @param allowed true to allow, false to revoke.
     * @dev   Use this to extend the allowlist when onchain_risk_scorer._grade() is
     *        updated to output finer-grained grades (A+, A-, B+, B-, C+, etc.).
     */
    function setValidGrade(string calldata grade, bool allowed) external onlyOwner {
        uint256 len = bytes(grade).length;
        if (len == 0 || len > 3) revert InvalidGradeLength();
        _validGrades[keccak256(bytes(grade))] = allowed;
        emit ValidGradeSet(grade, allowed);
    }

    // ── Read functions ───────────────────────────────────────────────────

    /**
     * @notice Check whether a grade string is in the current allowlist.
     */
    function isValidGrade(string calldata grade) external view returns (bool) {
        return _validGrades[keccak256(bytes(grade))];
    }

    /**
     * @notice Get the latest attestation for a contract on a specific chain.
     */
    function getAttestation(address _contractAddress, string calldata _chain)
        external
        view
        returns (Attestation memory)
    {
        Attestation memory att = attestations[_contractAddress][_chain];
        if (att.attestedAt == 0) revert AttestationNotFound();
        return att;
    }

    // ── Admin/Pausable functions ─────────────────────────────────────────

    function pause()   external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }
}

contracts/GuardianThreatFeedRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title GuardianThreatFeedRegistry
 * @notice On-chain registry of known malicious addresses (EVM and non-EVM).
 *
 * @dev    Access control: all write functions restricted to onlyOwner, consistent
 *         with the other 4 GuardianAI on-chain contracts. The previous AccessControl /
 *         FEED_WRITER_ROLE pattern was removed (TF-1): the role was only ever granted
 *         to the deployer EOA, and transferOwnership() does not transfer AccessControl
 *         roles — leaving the deployer with unilateral write access after ownership
 *         transfer to the GuardianTimelock.
 *
 *         Removal algorithm (TF-2/TF-3): evmAddresses and stringAddresses are bounded
 *         by MAX_EVM_REGISTRY_SIZE and MAX_STRING_REGISTRY_SIZE respectively.  Removal
 *         is O(1) via index mappings (evmIndex / stringIndex) rather than the previous
 *         O(n) linear scan.  On remove, the target slot is filled by swapping in the
 *         last element, the swapped element's index entry is updated, and the removed
 *         element's index entry is deleted.
 */
contract GuardianThreatFeedRegistry is Ownable2Step, Pausable {

    // ── Constants ────────────────────────────────────────────────────────

    uint256 public constant MAX_EVM_REGISTRY_SIZE    = 10_000;
    uint256 public constant MAX_STRING_REGISTRY_SIZE =  5_000;

    // ── Custom errors ────────────────────────────────────────────────────

    error EvmRegistryFull();
    error StringRegistryFull();

    // ── State ────────────────────────────────────────────────────────────

    struct ThreatInfo {
        bool    isMalicious;
        string  reason;
        uint256 addedAt;
    }

    // EVM address registry
    mapping(address => ThreatInfo) public evmRegistry;
    address[] public evmAddresses;
    /// @dev 0-based position of each address in evmAddresses[].
    ///      Only valid when evmRegistry[addr].isMalicious == true.
    mapping(address => uint256) private evmIndex;

    // String address registry (Solana, BTC, etc.)
    mapping(string => ThreatInfo) public stringRegistry;
    string[] public stringAddresses;
    /// @dev 0-based position of each string address, keyed by keccak256(abi.encodePacked(addr)).
    ///      Only valid when stringRegistry[addr].isMalicious == true.
    mapping(bytes32 => uint256) private stringIndex;

    // ── Events ───────────────────────────────────────────────────────────

    event AddressAdded(address indexed malicious, string reason);
    event AddressRemoved(address indexed malicious);
    event StringAddressAdded(string indexed malicious, string reason);
    event StringAddressRemoved(string indexed malicious);

    // ── Constructor ──────────────────────────────────────────────────────

    constructor() Ownable(msg.sender) {}

    // ── EVM write functions ──────────────────────────────────────────────

    /**
     * @notice Add a malicious EVM address to the registry.
     * @dev    Reverts with EvmRegistryFull if the registry has reached MAX_EVM_REGISTRY_SIZE.
     *         Re-adding an already-registered address only updates its reason/timestamp (no
     *         double-push to the array and no cap check).
     */
    function addAddress(address _malicious, string calldata _reason)
        external
        onlyOwner
        whenNotPaused
    {
        require(_malicious != address(0), "Invalid address");
        if (!evmRegistry[_malicious].isMalicious) {
            if (evmAddresses.length >= MAX_EVM_REGISTRY_SIZE) revert EvmRegistryFull();
            evmIndex[_malicious] = evmAddresses.length;
            evmAddresses.push(_malicious);
        }
        evmRegistry[_malicious] = ThreatInfo({
            isMalicious: true,
            reason:      _reason,
            addedAt:     block.timestamp
        });
        emit AddressAdded(_malicious, _reason);
    }

    /**
     * @notice Remove an EVM address from the registry. O(1) via index mapping.
     * @dev    Fills the vacated slot by swapping in the last element, updates that
     *         element's index entry, then pops.  Handles the single-element and
     *         last-element edge cases (idx == lastIdx) without a swap.
     */
    function removeAddress(address _malicious)
        external
        onlyOwner
        whenNotPaused
    {
        require(evmRegistry[_malicious].isMalicious, "Address not in registry");

        // CEI: state writes before any potential callbacks
        evmRegistry[_malicious].isMalicious = false;
        evmRegistry[_malicious].reason = "";

        uint256 idx     = evmIndex[_malicious];
        uint256 lastIdx = evmAddresses.length - 1;

        if (idx != lastIdx) {
            // Swap last element into the vacated slot
            address last = evmAddresses[lastIdx];
            evmAddresses[idx] = last;
            evmIndex[last] = idx;   // update the moved element's index
        }
        evmAddresses.pop();
        delete evmIndex[_malicious];

        emit AddressRemoved(_malicious);
    }

    /**
     * @notice Batch-add EVM addresses. All-or-nothing.
     * @dev    Reverts with EvmRegistryFull if any new entry would exceed the cap.
     *         Addresses already in the registry are updated in place (no cap check
     *         for them, no re-push).
     */
    function addAddressesBatch(
        address[] calldata _addresses,
        string[]  calldata _reasons
    ) external onlyOwner whenNotPaused {
        require(_addresses.length == _reasons.length, "Length mismatch");
        require(_addresses.length <= 50, "Batch too large");

        for (uint256 i = 0; i < _addresses.length; i++) {
            address addr = _addresses[i];
            require(addr != address(0), "Invalid address");
            if (!evmRegistry[addr].isMalicious) {
                if (evmAddresses.length >= MAX_EVM_REGISTRY_SIZE) revert EvmRegistryFull();
                evmIndex[addr] = evmAddresses.length;
                evmAddresses.push(addr);
            }
            evmRegistry[addr] = ThreatInfo({
                isMalicious: true,
                reason:      _reasons[i],
                addedAt:     block.timestamp
            });
            emit AddressAdded(addr, _reasons[i]);
        }
    }

    // ── String-address write functions ───────────────────────────────────

    /**
     * @notice Add a malicious non-EVM string address (e.g. Solana, BTC) to the registry.
     * @dev    Reverts with StringRegistryFull if the registry has reached MAX_STRING_REGISTRY_SIZE.
     */
    function addStringAddress(string calldata _malicious, string calldata _reason)
        external
        onlyOwner
        whenNotPaused
    {
        require(bytes(_malicious).length > 0, "Empty string address");
        if (!stringRegistry[_malicious].isMalicious) {
            if (stringAddresses.length >= MAX_STRING_REGISTRY_SIZE) revert StringRegistryFull();
            bytes32 key = keccak256(abi.encodePacked(_malicious));
            stringIndex[key] = stringAddresses.length;
            stringAddresses.push(_malicious);
        }
        stringRegistry[_malicious] = ThreatInfo({
            isMalicious: true,
            reason:      _reason,
            addedAt:     block.timestamp
        });
        emit StringAddressAdded(_malicious, _reason);
    }

    /**
     * @notice Remove a non-EVM string address from the registry. O(1) via index mapping.
     */
    function removeStringAddress(string calldata _malicious)
        external
        onlyOwner
        whenNotPaused
    {
        require(stringRegistry[_malicious].isMalicious, "Address not in registry");

        // CEI: state writes first
        stringRegistry[_malicious].isMalicious = false;
        stringRegistry[_malicious].reason = "";

        bytes32 key     = keccak256(abi.encodePacked(_malicious));
        uint256 idx     = stringIndex[key];
        uint256 lastIdx = stringAddresses.length - 1;

        if (idx != lastIdx) {
            string memory last = stringAddresses[lastIdx];
            stringAddresses[idx] = last;
            stringIndex[keccak256(abi.encodePacked(last))] = idx;
        }
        stringAddresses.pop();
        delete stringIndex[key];

        emit StringAddressRemoved(_malicious);
    }

    /**
     * @notice Batch-add non-EVM string addresses. All-or-nothing.
     */
    function addStringAddressesBatch(
        string[] calldata _addresses,
        string[] calldata _reasons
    ) external onlyOwner whenNotPaused {
        require(_addresses.length == _reasons.length, "Length mismatch");
        require(_addresses.length <= 50, "Batch too large");

        for (uint256 i = 0; i < _addresses.length; i++) {
            require(bytes(_addresses[i]).length > 0, "Empty string address");
            if (!stringRegistry[_addresses[i]].isMalicious) {
                if (stringAddresses.length >= MAX_STRING_REGISTRY_SIZE) revert StringRegistryFull();
                bytes32 key = keccak256(abi.encodePacked(_addresses[i]));
                stringIndex[key] = stringAddresses.length;
                stringAddresses.push(_addresses[i]);
            }
            stringRegistry[_addresses[i]] = ThreatInfo({
                isMalicious: true,
                reason:      _reasons[i],
                addedAt:     block.timestamp
            });
            emit StringAddressAdded(_addresses[i], _reasons[i]);
        }
    }

    // ── Read functions ───────────────────────────────────────────────────

    function isMalicious(address _query) external view returns (bool, string memory) {
        ThreatInfo memory info = evmRegistry[_query];
        return (info.isMalicious, info.reason);
    }

    function isMaliciousString(string calldata _query) external view returns (bool, string memory) {
        ThreatInfo memory info = stringRegistry[_query];
        return (info.isMalicious, info.reason);
    }

    function evmAddressCount() external view returns (uint256) {
        return evmAddresses.length;
    }

    function stringAddressCount() external view returns (uint256) {
        return stringAddresses.length;
    }

    // ── Admin/Pausable functions ─────────────────────────────────────────

    function pause()   external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }
}

contracts/GuardianTimelock.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/governance/TimelockController.sol";

/**
 * @title GuardianTimelock
 * @notice Timelock controller for Guardian protocol admin operations.
 * All 6 Guardian contracts transfer ownership to this timelock,
 * enforcing a minimum 24-hour delay on all privileged operations.
 *
 * Roles:
 * - PROPOSER_ROLE: multi-sig wallet that proposes operations
 * - EXECUTOR_ROLE: address(0) = anyone can execute after delay. This is an intentional OpenZeppelin
 *   TimelockController pattern; security relies on the restricted proposer set, not the executor.
 * - CANCELLER_ROLE: same as proposer (can cancel pending ops)
 * - TIMELOCK_ADMIN_ROLE: renounced after setup (no admin backdoor)
 */
contract GuardianTimelock is TimelockController {
    uint256 public constant MIN_DELAY = 24 hours;

    constructor(
        address[] memory proposers,
        address[] memory executors,
        address admin
    )
        TimelockController(
            MIN_DELAY,
            proposers,
            executors,
            admin
        )
    {}
}

